class_name SaveManager
extends Node

const SAVE_PATH := "user://save_data.json"

var unlocked_levels: int = 1
var best_times: Dictionary = {}


func _ready() -> void:
	load_game()


func save_game() -> void:
	var data := {
		"unlocked_levels": unlocked_levels,
		"best_times": best_times
	}
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file:
		var json_string := JSON.stringify(data, "\t")
		file.store_string(json_string)
		file.close()


func load_game() -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return

	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file:
		var json_string := file.get_as_text()
		file.close()

		var json := JSON.new()
		var error := json.parse(json_string)
		if error == OK and json.data is Dictionary:
			var data: Dictionary = json.data
			unlocked_levels = int(data.get("unlocked_levels", 1))
			best_times = data.get("best_times", {})


func unlock_next_level(level_number: int) -> void:
	if level_number > unlocked_levels:
		unlocked_levels = level_number
		save_game()


func save_best_time(level_name: String, time_seconds: float) -> void:
	var current_best: float = float(best_times.get(level_name, 999999.0))
	if time_seconds < current_best:
		best_times[level_name] = time_seconds
		save_game()

class_name Goal
extends Area2D

@export_file("*.tscn") var next_level_path: String = ""
@export var unlocks_level: int = 2


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if body is CharacterBody2D:
		_reach_goal()


func _reach_goal() -> void:
	if unlocks_level > 0:
		SaveManager.unlock_next_level(unlocks_level)

	if next_level_path.is_empty():
		return
	get_tree().change_scene_to_file(next_level_path)

class_name LevelSelect
extends Control

@onready var level_1_button: Button = $Level1Button
@onready var level_2_button: Button = $Level2Button


func _ready() -> void:
	var unlocked: int = SaveManager.unlocked_levels
	if level_1_button:
		level_1_button.disabled = unlocked < 1
		level_1_button.pressed.connect(_on_level_1_pressed)
	if level_2_button:
		level_2_button.disabled = unlocked < 2
		level_2_button.pressed.connect(_on_level_2_pressed)


func _on_level_1_pressed() -> void:
	get_tree().change_scene_to_file("res://levels/level_1.tscn")


func _on_level_2_pressed() -> void:
	get_tree().change_scene_to_file("res://levels/level_2.tscn")

class_name MainMenu
extends Control

@onready var play_button: Button = $PlayButton
@onready var quit_button: Button = $QuitButton


func _ready() -> void:
	if play_button:
		play_button.pressed.connect(_on_play_button_pressed)
	if quit_button:
		quit_button.pressed.connect(_on_quit_button_pressed)


func _on_play_button_pressed() -> void:
	get_tree().change_scene_to_file("res://ui/level_select.tscn")


func _on_quit_button_pressed() -> void:
	get_tree().quit()

class_name PauseMenu
extends Control

@onready var resume_button: Button = $ResumeButton
@onready var main_menu_button: Button = $MainMenuButton


func _ready() -> void:
	hide()
	process_mode = Node.PROCESS_MODE_ALWAYS

	if resume_button:
		resume_button.pressed.connect(_on_resume_button_pressed)
	if main_menu_button:
		main_menu_button.pressed.connect(_on_main_menu_button_pressed)


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("ui_cancel"):
		if get_tree().paused:
			resume()
		else:
			pause()


func pause() -> void:
	show()
	get_tree().paused = true


func resume() -> void:
	hide()
	get_tree().paused = false


func _on_resume_button_pressed() -> void:
	resume()


func _on_main_menu_button_pressed() -> void:
	resume()
	get_tree().change_scene_to_file("res://ui/main_menu.tscn")

