class_name LevelSelect
extends Control

@export var level_buttons: Array[Button] = []


func _ready() -> void:
	var unlocked: int = SaveManager.unlocked_levels
	for i in range(level_buttons.size()):
		var level_number := i + 1
		var button := level_buttons[i]
		if level_number <= unlocked:
			button.disabled = false
			button.pressed.connect(_on_level_button_pressed.bind(level_number))
		else:
			button.disabled = true


func _on_level_button_pressed(level_number: int) -> void:
	var level_path := "res://levels/level_0%d.tscn" % level_number
	get_tree().change_scene_to_file(level_path)

